 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Any monochromatic solid rectangle at least 5x5 is marked with color 4.
    # Enumerate maximal vertical spans and their shared horizontal runs.
    for r0 in range(h):
        for r1 in range(r0 + 4, h):
            for c0 in range(w):
                color = grid[r0][c0]
                if any(grid[r][c0] != color for r in range(r0, r1 + 1)):
                    continue
                c1 = c0
                while c1 < w and all(grid[r][c1] == color for r in range(r0, r1 + 1)):
                    c1 += 1
                if c1 - c0 >= 5 and (c0 == 0 or not all(grid[r][c0 - 1] == color for r in range(r0, r1 + 1))):
                    if (r0 == 0 or not all(grid[r0 - 1][c] == color for c in range(c0, c1))) and (r1 == h - 1 or not all(grid[r1 + 1][c] == color for c in range(c0, c1))):
                        for r in range(r0, r1 + 1):
                            for c in range(c0, c1):
                                out[r][c] = 4
    return out
